// PDF-Text in strukturiertes Markdown umwandeln
const rawText = $input.first().json.data;

// Basis-Bereinigung
let text = rawText
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// Einfache Heuristik: Zeilen in GROSSBUCHSTABEN werden zu Headings
const lines = text.split('\n');
const mdLines = lines.map(line => {
  const trimmed = line.trim();
  // Komplett uppercase und kurz = Heading
  if (trimmed.length > 3 && trimmed.length < 80 && trimmed === trimmed.toUpperCase() && /[A-Z]/.test(trimmed)) {
    return `\n## ${trimmed}\n`;
  }
  return trimmed;
});

const markdown = mdLines.join('\n');
const filename = $input.first().json.fileName || 'dokument';
const baseName = filename.replace(/\.pdf$/i, '');

return [{
  json: {
    fileName: `${baseName}.md`,
    markdown: markdown,
    originalFileName: filename,
    charCount: markdown.length,
    extractedAt: new Date().toISOString()
  }
}];
